<template>
  <LoadingElement v-if="authStore.isLoading" />
  <div class="main bg-primary" v-else>

    <!-- Top bar -->
    <div class="rowSpaceBetween fullWidth mb-5">
      <TopDeck
        firstElement="Mon"
        secondElement="profil"
        :coloredSecond="true"
      />
      <div class="pp-topbar">
        <ThemeToggle />
        <AccountToggle displayLogout="true" />
      </div>
    </div>

    <!-- Bannière mot de passe -->
    <div class="pp-banner rounded-xl mb-6" @click="changePassword">
      <div>
        <h2 class="pp-banner__title">Sécurisez votre compte</h2>
        <p class="pp-banner__sub">Mettez à jour votre mot de passe pour garder votre compte protégé</p>
      </div>
      <button class="pp-banner__btn">
        <v-icon size="15">mdi-lock-reset</v-icon>
        Changer le mot de passe
      </button>
    </div>

    <!-- Bloc principal -->
    <div class="pp-container">

      <!-- Header section -->
      <div class="pp-section-header">
        <div class="pp-section-header__left">
          <div class="pp-avatar">
            <span class="pp-avatar__letter">{{ avatarLetter }}</span>
          </div>
          <div>
            <h1 class="pp-username">{{ authStore.userInfos?.username || "—" }}</h1>
            <span class="pp-email">{{ authStore.userInfos?.email || "—" }}</span>
          </div>
        </div>
      </div>

