            Adresse e-mail
          </div>
          <span class="pp-info-row__value">{{ authStore.userInfos?.email || "—" }}</span>
        </div>
      </div>
    </div>

    <!-- Stats de santé -->
    <div class="pp-container mt-4">
      <div class="pp-section-title mb-3">Statistiques de santé</div>
      <HealthStatsBloc />
    </div>

    <!-- Préférences & infos complémentaires -->
    <div class="pp-container mt-4">
      <div class="pp-prefs-header mb-3">
        <span class="pp-section-title">Mes préférences</span>
        <button class="pp-btn-edit" @click="router.push('/edit_preferences')">
          <v-icon size="13">mdi-pencil</v-icon>
          Modifier
        </button>
      </div>
      <Info_display_bloc :user="authStore.userInfos" />
    </div>

  </div>

  <!-- Snackbar -->
  <v-snackbar v-model="showSnack" :color="snackColor" :timeout="2000" location="bottom">
    {{ snackMessage }}
  </v-snackbar>

  <!-- Modal mot de passe -->
  <v-dialog v-model="showPasswordDialog" max-width="420">
    <div class="pp-modal">
      <div class="pp-modal__header">
        <div class="pp-modal__title">
          <v-icon class="pp-modal__icon">mdi-lock-reset</v-icon>
          Changer mon mot de passe
        </div>
        <button class="pp-modal__close" @click="showPasswordDialog = false">
          <v-icon size="18">mdi-close</v-icon>
        </button>
      </div>

      <div class="pp-modal__body">
        <p class="pp-modal__hint-top">
          Entrez votre adresse e-mail et nous vous enverrons un lien pour réinitialiser votre mot de passe.
        </p>
        <v-text-field
          v-model="email"
          type="email"
          label="Votre e-mail"
          variant="outlined"
          density="compact"
          required
          prepend-inner-icon="mdi-email-outline"
          class="pp-modal__field"
        />
        <button
          class="pp-modal__submit"
          :disabled="loading"
          @click="onSubmit"
        >
          <v-icon size="15" class="mr-1">mdi-email-fast-outline</v-icon>
          {{ loading ? "Envoi…" : "Envoyer le lien" }}
        </button>
        <p v-if="done" class="pp-modal__success">
          Si un compte existe pour cet e-mail, un message vient d'être envoyé.
        </p>
        <p v-if="error" class="pp-modal__error">{{ error }}</p>
      </div>

      <div class="pp-modal__footer">
        <button class="pp-modal__ghost" @click="showPasswordDialog = false">Fermer</button>
      </div>
    </div>
  </v-dialog>
</template>

<script>
import { ref, computed } from "vue";
import { getAuth, signOut } from "firebase/auth";
import { useRouter } from "vue-router";
import TopDeck from "../Utils/TopDeck.vue";
import LoadingElement from "../Animations/LoadingElement.vue";
import { useAuthStore } from "@/store/auth_store";
import Info_display_bloc from "./InfoDisplayBlock.vue";
import { requestPasswordReset } from "@/service/auth_service";
import HealthStatsBloc from "./HealthStatsBloc.vue";
import ThemeToggle from "@/components/Utils/ThemeToggle.vue";
import AccountToggle from "@/components/Utils/AccountToggle.vue";

export default {
  name: "ProfilPage",
  components: {
    LoadingElement,
    TopDeck,
    Info_display_bloc,
    HealthStatsBloc,
    ThemeToggle,
    AccountToggle,
  },
  setup() {
    const router = useRouter();
    const auth = getAuth();
    const authStore = useAuthStore();

    const showSnack = ref(false);
    const snackMessage = ref("");
    const snackColor = ref("success");

    const showPasswordDialog = ref(false);
    const email = ref("");
    const loading = ref(false);
    const done = ref(false);
    const error = ref("");

    const avatarLetter = computed(() => {
      const name = authStore.userInfos?.username || authStore.userInfos?.email || "?";
      return name.charAt(0).toUpperCase();
    });

    const changePassword = () => {
      showPasswordDialog.value = true;
    };

    async function onSubmit() {
      loading.value = true;
      error.value = "";
      try {
        await requestPasswordReset(email.value);
        done.value = true;
      } catch (e) {
        console.error("requestPasswordReset error", e);
        done.value = true;
      } finally {
        loading.value = false;
      }
    }

    const handleSignout = () => {
      signOut(auth)
        .then(() => { router.push("/login"); })
        .catch((err) => { console.error(err); });
    };

    return {
      authStore,
      showSnack,
      snackMessage,
      snackColor,
      showPasswordDialog,
      email,
      loading,
      done,
      error,
      avatarLetter,
      router,
      onSubmit,
      handleSignout,
      changePassword,
    };
  },
};
</script>

