    getBaseIngredients,
    deleteBaseIngredient,
    updateBaseIngredient,
    updateCategoryImage,
    getCategoryMeta,
    AVAILABLE_STORES,
} from '@/service/base_ingredient_service';
import {
    getHiddenBaseIngredients,
    deleteHiddenBaseIngredient,
} from '@/service/hidden_base_ingredient_service';
import AccountToggle from "@/components/Utils/AccountToggle.vue";
import SeasonalityPicker from "@/components/Kitchen/Ingredients/SeasonalityPicker.vue";

export default {
    name: "BaseIngredientsCatalog",
    components: { LoadingElement, TopDeck, ThemeToggle, AccountToggle, ConfirmDialog, SeasonalityPicker },
    setup() {
        const authStore = useAuthStore();
        const errorMessage = ref("");
        const snack = ref({ show: false, text: "" });
        const router = useRouter();

        const WINTER = new Set([11, 0, 1, 2]);
        const SUMMER = new Set([5, 6, 7, 8]);
        function getSeasonIcon(months) {
            if (!Array.isArray(months) || !months.length) return '';
            const hasWinter = months.some(m => WINTER.has(m));
            const hasSummer = months.some(m => SUMMER.has(m));
            if (hasWinter && hasSummer) return '❄️☀️';
            if (hasWinter) return '❄️';
            if (hasSummer) return '☀️';
            return '🌿';
        }

        const ingredients = ref([]);
        const isLoadingIngredients = ref(false);
        const searchQuery = ref("");
        const selectedCategory = ref("Toutes");
        const selectedIngredient = ref(null);
        const seasonFilter = ref(null); // null | 'winter' | 'summer' | 'frozen'
        const isAdmin = computed(() => authStore.userInfos?.role === 'admin');

        // ---- Suppression ----
        const confirmDialogOpen = ref(false);
        const ingredientToDelete = ref(null);
        const confirmDialogMessage = computed(() => {
            const name = ingredientToDelete.value?.productName || ingredientToDelete.value?.id || "";
            return name
                ? `Supprimer l'ingrédient de base "${name}" ?`
                : "Supprimer cet ingrédient de base ?";
        });

        // ---- Catégories ----
        const categoryMeta = ref({});

        const CATEGORY_META = {
            'légumes':      { emoji: '🥦', label: 'Légumes' },
            'fruits':       { emoji: '🍎', label: 'Fruits' },
            'poissons':     { emoji: '🐟', label: 'Poissons' },
            'légumineuses': { emoji: '🫘', label: 'Légumineuses' },
            'huiles':       { emoji: '🫙', label: 'Huiles' },
            'farines':      { emoji: '🌾', label: 'Farines' },
            'épices':       { emoji: '🌶️', label: 'Épices' },
        };

        const categories = computed(() => {
            const cats = new Set(
                ingredients.value.map((i) => i.category).filter(Boolean)
            );
            return ["Toutes", ...Array.from(cats).sort()];
        });

        const categoryCards = computed(() => {
            return categories.value
                .filter(c => c !== "Toutes")
                .map(cat => {
                    const key = cat.toLowerCase().trim();
                    const meta = Object.entries(CATEGORY_META).find(([k]) => key.includes(k));
                    const count = ingredients.value.filter(i => i.category === cat).length;
                    const metaImg = categoryMeta.value?.[cat]?.imageUrl || null;
                    return {
                        key: cat,
                        label: meta ? meta[1].label : cat,
                        emoji: meta ? meta[1].emoji : '🍽️',
                        imageUrl: metaImg,
                        count,
                    };
                });
        });

        // ---- Dialog image catégorie ----
        const categoryImageDialog = ref({ open: false, key: '', label: '', imageUrl: '', saving: false });

        function openCategoryImageDialog(cat) {
            categoryImageDialog.value = {
                open: true,
                key: cat.key,
                label: cat.label,
                imageUrl: cat.imageUrl || '',
                saving: false,
            };
        }

        async function saveCategoryImage() {
            categoryImageDialog.value.saving = true;
            try {
                await updateCategoryImage(
                    categoryImageDialog.value.key,
                    categoryImageDialog.value.imageUrl,
                    authStore.userInfos?.role
                );
                // Mise à jour locale
                categoryMeta.value = {
                    ...categoryMeta.value,
                    [categoryImageDialog.value.key]: { imageUrl: categoryImageDialog.value.imageUrl },
                };
                snack.value = { show: true, text: "Image de catégorie mise à jour ✅" };
                categoryImageDialog.value.open = false;
            } catch (e) {
                console.error("Erreur saveCategoryImage:", e);
                errorMessage.value = "Erreur lors de la mise à jour de l'image.";
            } finally {
                categoryImageDialog.value.saving = false;
            }
        }

        // ---- Constantes scores ----
        const NUTRISCORE_OPTIONS = ['A', 'B', 'C', 'D', 'E'];
        const NOVA_OPTIONS = [1, 2, 3, 4];

        const ingredientCategories = [
            "Fruits", "Légumes", "Légumineuses", "Céréales", "Viandes",
            "Poissons", "Produits laitiers", "Œufs", "Matières grasses",
            "Épices", "Herbes", "Autres"
        ];

        function nutriscoreColor(v) {
            const map = { A: 'green', B: 'light-green', C: 'yellow-darken-3', D: 'orange', E: 'red' };
            return map[v] || 'grey';
        }
        function novaColor(v) {
            const map = { 1: 'green', 2: 'light-green', 3: 'orange', 4: 'red' };
            return map[v] || 'grey';
        }
        function buildNovaGroup(novaValue) {
            if (!novaValue) return { color: 'grey', string: '' };
            return { color: novaColor(novaValue), string: `nova.${novaValue}` };
        }

        // Utilitaire: parse une valeur numérique d'un string type "264 kcal"
        function parseNumFromStr(s) {
            const m = String(s ?? '').match(/-?\d+(\.\d+)?/);
            return m ? Number(m[0]) : null;
        }

        // ---- Dialog édition ingrédient ----
        const emptyEditForm = () => ({
            open: false, saving: false, id: null,
            name: "", brand: "", category: "",
            poids: null, kcal: null, lipides: null, glucides: null,
            proteines: null, fibres: null, sel: null, sucre: null, agSatures: null,
            productImage: "", productLink: "",
            nutriscore: "", novaValue: null,
            availableStores: [],
            seasonMonths: [],
            isFrozen: false,
        });

        const editDialog = ref(emptyEditForm());

        const canSaveEdit = computed(() =>
            editDialog.value.name?.trim() &&
            editDialog.value.kcal !== null &&
            editDialog.value.lipides !== null &&
            editDialog.value.glucides !== null &&
            editDialog.value.proteines !== null
        );

        function getNutrimentValue(nutriments_map, key) {
            const entry = (nutriments_map || []).find(n => n.key === key);
            return entry ? parseNumFromStr(entry.value) : null;
        }

        function openEditDialog(item) {
            const nm = item.nutriments_map || [];
            editDialog.value = {
                open: true,
                saving: false,
                id: item.id,
                name: item.productName || "",
                brand: item.productBrand || "",
                category: item.category || "",
                poids: item.servingQuantity || null,
                productImage: item.productImage || "",
                productLink: item.productLink || "",
                nutriscore: item.nutriscore || "",
                novaValue: item.novaGroup?.string ? parseInt(item.novaGroup.string.replace('nova.', '')) : null,
                availableStores: Array.isArray(item.availableStores) ? [...item.availableStores] : [],
                seasonMonths: Array.isArray(item.seasonMonths) ? [...item.seasonMonths] : [],
                isFrozen: item.isFrozen || false,
                kcal: getNutrimentValue(nm, 'energy-kcal'),
                lipides: getNutrimentValue(nm, 'fat'),
                agSatures: getNutrimentValue(nm, 'saturated-fat'),
                glucides: getNutrimentValue(nm, 'carbohydrates'),
                sucre: getNutrimentValue(nm, 'sugar'),
                proteines: getNutrimentValue(nm, 'proteins'),
                fibres: getNutrimentValue(nm, 'fiber'),
                sel: getNutrimentValue(nm, 'salt'),
            };
        }

        function toggleEditStore(store) {
            const arr = editDialog.value.availableStores;
            const idx = arr.indexOf(store);
            if (idx === -1) arr.push(store);
            else arr.splice(idx, 1);
        }

        async function saveEditIngredient() {
            if (!canSaveEdit.value) return;
            editDialog.value.saving = true;
            try {
                const f = editDialog.value;
                const nutriments_map = [
                    { key: "energy-kcal", value: f.kcal != null ? `${f.kcal} kcal` : "" },
                    { key: "fat", value: f.lipides != null ? `${f.lipides} g` : "" },
                    { key: "saturated-fat", value: f.agSatures != null ? `${f.agSatures} g` : "" },
                    { key: "carbohydrates", value: f.glucides != null ? `${f.glucides} g` : "" },
                    { key: "sugar", value: f.sucre != null ? `${f.sucre} g` : "" },
                    { key: "proteins", value: f.proteines != null ? `${f.proteines} g` : "" },
                    { key: "fiber", value: f.fibres != null ? `${f.fibres} g` : "" },
                    { key: "salt", value: f.sel != null ? `${f.sel} g` : "" },
                ].filter(n => n.value);

                const updatedData = {
                    productName: f.name.trim(),
                    productBrand: f.brand || "",
                    category: f.category || "",
                    servingQuantity: f.poids || null,
                    servingSize: f.poids ? `${f.poids} g` : null,
                    productImage: f.productImage || "",
                    productLink: f.productLink || "",
                    nutriscore: f.nutriscore || "",
                    novaGroup: buildNovaGroup(f.novaValue),
                    availableStores: [...f.availableStores],
                    seasonMonths: [...f.seasonMonths],
                    isFrozen: f.isFrozen || false,
                    nutriments_map,
                };

                // Sauvegarde selon la collection d'origine (base ou cachée)
                const currentItem = ingredients.value.find(i => i.id === f.id);
                let merged;
                if (currentItem?.isHidden) {
                    // Ingrédient caché → écrire dans HiddenBaseIngredients/all
                    const hiddenRef = doc(db, "HiddenBaseIngredients", "all");
                    const snap = await getDoc(hiddenRef);
                    const hiddenData = snap.exists() ? snap.data() : {};
                    merged = { ...(hiddenData[f.id] || {}), ...updatedData, hidden: true };
                    await setDoc(hiddenRef, { [f.id]: merged }, { merge: true });
                } else {
                    merged = await updateBaseIngredient(f.id, updatedData, authStore.userInfos?.role);
                }

                // Mise à jour locale
                const idx = ingredients.value.findIndex(i => i.id === f.id);
                if (idx !== -1) {
                    ingredients.value[idx] = { ...ingredients.value[idx], ...merged };
                }
                if (selectedIngredient.value?.id === f.id) {
                    selectedIngredient.value = { ...selectedIngredient.value, ...merged };
                }

                snack.value = { show: true, text: "Ingrédient mis à jour ✅" };
                editDialog.value.open = false;
            } catch (err) {
                console.error("Erreur saveEditIngredient:", err);
                errorMessage.value = "Erreur lors de la mise à jour de l'ingrédient.";
            } finally {
                editDialog.value.saving = false;
            }
        }

        // ---- Sélection panel latéral ----
        function selectIngredient(item) {
            if (selectedIngredient.value?.id === item.id) {
                selectedIngredient.value = null;
            } else {
                selectedIngredient.value = item;
            }
        }

        // ---- Ajout à la collection utilisateur ----
        const addedIds = ref(new Set());

        function getKcal(item) {
            const entry = (item.nutriments_map || []).find(n => n.key === 'energy-kcal');
            if (!entry) return '—';
            const m = String(entry.value || '').match(/\d+(\.\d+)?/);
            return m ? `${Math.round(Number(m[0]))} kcal` : '—';
        }

        async function addItemToUserCollection(item) {
            if (!authStore?.userid) {
                errorMessage.value = "Utilisateur non connecté.";
                return;
            }
            try {
                const res = await addItemToUserCollectionService(authStore.userid, item, item.id);
                if (res?.existed) {
                    snack.value = { show: true, text: "Déjà dans votre collection." };
                } else {
                    snack.value = { show: true, text: "Ajouté à votre collection." };
                }
                // Dans les deux cas, marquer comme ajouté
                const next = new Set(addedIds.value);
                next.add(item.id);
                addedIds.value = next;
            } catch (e) {
                console.error('Erreur ajout ingrédient utilisateur:', e);
                errorMessage.value = "Erreur lors de l'ajout de l'ingrédient.";
            }
        }

        // ---- Suppression ----
        async function deleteBaseIngredientItem(item) {
            if (!item?.id) return;
            if (!isAdmin.value) {
                errorMessage.value = "Action réservée aux administrateurs.";
                return;
            }
            try {
                await deleteBaseIngredient(item.id, authStore.userInfos?.role);
                ingredients.value = ingredients.value.filter((ing) => ing.id !== item.id);
                if (selectedIngredient.value?.id === item.id) selectedIngredient.value = null;
                snack.value = { show: true, text: "Ingrédient supprimé." };
            } catch (e) {
                console.error("Erreur suppression ingrédient de base:", e);
                errorMessage.value = "Erreur lors de la suppression de l'ingrédient.";
            }
        }

        function requestDelete(item) {
            if (!item || !isAdmin.value) return;
            ingredientToDelete.value = item;
            confirmDialogOpen.value = true;
        }

        function cancelDeleteBaseIngredient() {
            confirmDialogOpen.value = false;
            ingredientToDelete.value = null;
        }

        async function confirmDeleteBaseIngredient() {
            if (!ingredientToDelete.value) return;
            const item = ingredientToDelete.value;
            ingredientToDelete.value = null;
            confirmDialogOpen.value = false;
            await deleteBaseIngredientItem(item);
        }

        // ---- Promotion hidden → base ----
        const isPromoting = ref(false);
        async function promoteToBase(item) {
            if (!item?.id || !isAdmin.value) return;
            isPromoting.value = true;
            try {
                const promoted = { ...item };
                delete promoted.id;
                delete promoted.isHidden;
                delete promoted.hidden;

                // Insérer dans BaseIngredients/all
                const baseRef = doc(db, "BaseIngredients", "all");
                await setDoc(baseRef, { [item.id]: promoted }, { merge: true });

                // Supprimer de HiddenBaseIngredients/all
                await deleteHiddenBaseIngredient(item.id, authStore.userInfos?.role);

                // Mise à jour locale
                const idx = ingredients.value.findIndex(i => i.id === item.id);
                if (idx !== -1) ingredients.value[idx] = { ...ingredients.value[idx], isHidden: false };
                if (selectedIngredient.value?.id === item.id) {
                    selectedIngredient.value = { ...selectedIngredient.value, isHidden: false };
                }

                snack.value = { show: true, text: "Ingrédient déplacé vers le catalogue ✅" };
            } catch (e) {
                console.error("Erreur promoteToBase:", e);
                errorMessage.value = "Erreur lors du déplacement de l'ingrédient.";
            } finally {
                isPromoting.value = false;
            }
        }

        // ---- Tri ----
        const sortKey = ref(null);
        const sortDir = ref('asc');
        const NUTRISCORE_ORDER = { A: 1, B: 2, C: 3, D: 4, E: 5 };

        function setSort(key) {
            if (sortKey.value === key) {
                sortDir.value = sortDir.value === 'asc' ? 'desc' : 'asc';
            } else {
                sortKey.value = key;
                sortDir.value = 'asc';
            }
        }

        function parseKcalNum(item) {
            const entry = (item.nutriments_map || []).find(n => n.key === 'energy-kcal');
            if (!entry) return -1;
            const m = String(entry.value || '').match(/\d+(\.\d+)?/);
            return m ? Number(m[0]) : -1;
        }

        // ---- Filtrage + tri ----
        const filteredIngredients = computed(() => {
            if (!ingredients.value) return [];
            let result = ingredients.value;

            if (selectedCategory.value && selectedCategory.value !== "Toutes") {
                result = result.filter(item => item.category === selectedCategory.value);
            }

            if (searchQuery.value.trim()) {
                const q = searchQuery.value.toLowerCase();
                result = result.filter(item =>
                    item.productName?.toLowerCase().includes(q) ||
                    item.category?.toLowerCase().includes(q) ||
                    item.productBrand?.toLowerCase().includes(q)
                );
            }

            if (seasonFilter.value === 'winter') {
                result = result.filter(item => Array.isArray(item.seasonMonths) && item.seasonMonths.some(m => WINTER.has(m)));
            } else if (seasonFilter.value === 'summer') {
                result = result.filter(item => Array.isArray(item.seasonMonths) && item.seasonMonths.some(m => SUMMER.has(m)));
            } else if (seasonFilter.value === 'frozen') {
                result = result.filter(item => item.isFrozen === true);
            }

            if (sortKey.value) {
                result = [...result].sort((a, b) => {
                    let va, vb;
                    if (sortKey.value === 'name') {
                        va = (a.productName || '').toLowerCase();
                        vb = (b.productName || '').toLowerCase();
                    } else if (sortKey.value === 'category') {
                        va = (a.category || '').toLowerCase();
                        vb = (b.category || '').toLowerCase();
                    } else if (sortKey.value === 'nutriscore') {
                        va = NUTRISCORE_ORDER[a.nutriscore] ?? 99;
                        vb = NUTRISCORE_ORDER[b.nutriscore] ?? 99;
                    } else if (sortKey.value === 'kcal') {
                        va = parseKcalNum(a);
                        vb = parseKcalNum(b);
                    }
                    if (va < vb) return sortDir.value === 'asc' ? -1 : 1;
                    if (va > vb) return sortDir.value === 'asc' ? 1 : -1;
                    return 0;
                });
            }

            return result;
        });

        // ---- Chargement ----
        onMounted(() => {
            watch(
                () => authStore.userInfos,
                async () => {
                    if (!authStore?.userid) return;
                    try {
                        isLoadingIngredients.value = true;
                        const [data, hiddenData, meta] = await Promise.all([
                            getBaseIngredients(),
                            getHiddenBaseIngredients(),
                            getCategoryMeta(),
                        ]);
                        const baseList = Object.entries(data).map(([id, value]) => ({
                            id, ...value, isHidden: false,
                        }));
                        const hiddenList = Object.entries(hiddenData).map(([id, value]) => ({
                            id, ...value, isHidden: true,
                        }));
                        ingredients.value = [...baseList, ...hiddenList];
                        categoryMeta.value = meta;
                    } catch (error) {
                        console.error("Erreur récupération ingrédients:", error);
                        errorMessage.value = "Erreur lors du chargement des ingrédients.";
                    } finally {
                        isLoadingIngredients.value = false;
                    }
                },
                { immediate: true }
            );
        });

        return {
            authStore,
            errorMessage,
            snack,
            router,
            searchQuery,
            selectedCategory,
            selectedIngredient,
            categories,
            addItemToUserCollection,
            addedIds,
            getKcal,
            selectIngredient,
            requestDelete,
            confirmDialogOpen,
            confirmDialogMessage,
            confirmDeleteBaseIngredient,
            cancelDeleteBaseIngredient,
            isLoadingIngredients,
            filteredIngredients,
            sortKey,
            sortDir,
            setSort,
            isAdmin,
            categoryCards,
            // dialog édition ingrédient
            editDialog,
            canSaveEdit,
            openEditDialog,
            saveEditIngredient,
            toggleEditStore,
            AVAILABLE_STORES,
            NUTRISCORE_OPTIONS,
            NOVA_OPTIONS,
            ingredientCategories,
            nutriscoreColor,
            novaColor,
            // dialog image catégorie
            categoryImageDialog,
            openCategoryImageDialog,
            saveCategoryImage,
            getSeasonIcon,
            seasonFilter,
            promoteToBase,
            isPromoting,
        };
    },
};
</script>

<style scoped>
