        box-shadow: 0 1px 4px rgba(0,0,0,0.2);
        transition: transform 0.15s, background 0.15s;
        z-index: 2;
    }
    .catCard__editBtn:hover { transform: scale(1.15); background: #fff; }

    /* Tri */
    .th-sortable {
        cursor: pointer;
        user-select: none;
        white-space: nowrap;
    }
    .th-sortable:hover { color: rgb(var(--v-theme-accent)); }
    .sort-arrow {
        font-size: 10px;
        margin-left: 4px;
        opacity: 0.45;
    }
    .th-sortable:hover .sort-arrow { opacity: 0.9; }

    /* Bouton ajouter — même style que BaseRecipeCard */
    .ing-add-btn {
        display: inline-flex;
        align-items: center;
        gap: 4px;
        font-size: 11px;
        font-weight: 500;
        color: rgb(var(--v-theme-accent));
        background: rgba(var(--v-theme-accent), 0.07);
        border: 0.5px solid rgba(var(--v-theme-accent), 0.25);
        border-radius: 999px;
        padding: 5px 12px;
        cursor: pointer;
        font-family: inherit;
        transition: background 0.15s;
        white-space: nowrap;
    }
    .ing-add-btn:hover:not(:disabled) {
        background: rgba(var(--v-theme-accent), 0.14);
    }
    .ing-add-btn--added {
        color: #2e7d32;
        background: rgba(46, 125, 50, 0.1);
        border-color: rgba(46, 125, 50, 0.35);
        cursor: not-allowed;
    }

    /* Tableau */
    .ingredient-row { cursor: pointer; transition: background 0.12s; min-height: 52px; height: 52px; }
    .ingredient-row:hover { background: rgba(0,0,0,0.04); }
    .row--selected { background: rgba(117,83,252,0.07) !important; }
